exercises.tests:
def _real(x, lo, hi):
    if lo > hi:
        raise ValueError("empty range")
    return lo if x < lo else hi if x > hi else x

_mutants = {
    "forgets the upper bound": lambda x, lo, hi: max(x, lo),
    "forgets the lower bound": lambda x, lo, hi: min(x, hi),
    "returns the wrong bound": lambda x, lo, hi: hi if x < lo else lo if x > hi else x,
    "treats hi as exclusive": lambda x, lo, hi: max(lo, min(x, hi - 1)),
    "never validates the range": lambda x, lo, hi: min(max(x, lo), hi),
}

def _passes(f, case):
    args, expected = case
    if expected is ValueError:
        try:
            f(*args)
        except ValueError:
            return True
        return False
    try:
        return f(*args) == expected
    except Exception:
        return False

assert isinstance(CASES, list) and CASES, "CASES must be a non-empty list"
for case in CASES:
    assert _passes(_real, case), f"the real clamp fails {case}: is the expected value right?"
for name, mutant in _mutants.items():
    assert any(not _passes(mutant, case) for case in CASES), f"the mutant that {name} survives"

